          "quantization_nm": 1.0
        }
      },
      "objectives": [
        {
          "objective_id": "obj_mean_r",
          "metric": "mean_reflectance",
          "sense": "minimize",
          "weight": 1.0,
          "target": 0.03,
          "region": {
            "wavelength_nm": [
              450.0,
              700.0
            ]
          },
          "admission_role": "score_only"
        }
      ],
      "tags": [
        "ar_coating",
        "sio2",
        "tio2",
        "glass"
      ]
    }
  ],
